import 'package:flutter/material.dart';

void main() => runApp(const RetailITApp());

class Ticket {
  Ticket({required this.id, required this.title, required this.category, required this.priority, required this.status, required this.description});
  final String id, title, category, priority, description;
  String status;
}

class RetailITApp extends StatefulWidget {
  const RetailITApp({super.key});
  @override State<RetailITApp> createState() => _RetailITAppState();
}

class _RetailITAppState extends State<RetailITApp> {
  final List<Ticket> tickets = [
    Ticket(id: '#IT-45821', title: 'VPN not connecting', category: 'Network & VPN', priority: 'High', status: 'In Progress', description: 'Unable to connect to company VPN. Getting error code 691.'),
    Ticket(id: '#IT-45820', title: 'Jupyter environment error', category: 'AI/ML Tools', priority: 'Medium', status: 'Open', description: 'Jupyter environment is failing to start for model training.'),
    Ticket(id: '#IT-45818', title: 'Request for GPU access', category: 'Cloud & Dev Tools', priority: 'Medium', status: 'Open', description: 'Need GPU access for an AI/ML training workload.'),
    Ticket(id: '#IT-45815', title: 'Laptop battery issue', category: 'Hardware', priority: 'Low', status: 'Resolved', description: 'Laptop battery drains quickly.'),
  ];
  int tab = 0;
  bool loggedIn = false;
  final employee = 'Aryan Tidake';

  @override
  Widget build(BuildContext context) {
    return MaterialApp(debugShowCheckedModeBanner: false, theme: _theme(), home: loggedIn ? AppShell(tickets: tickets, employee: employee, tab: tab, onTab: (i) => setState(() => tab = i), onCreate: _createTicket, onLogout: () => setState(() => loggedIn = false)) : LoginScreen(onLogin: () => setState(() => loggedIn = true)));
  }

  ThemeData _theme() => ThemeData(useMaterial3: true, scaffoldBackgroundColor: const Color(0xFFF5F7FB), colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF0066FF), brightness: Brightness.light), fontFamily: 'Arial', inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: Colors.white, border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide.none), enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide.none)));

  void _createTicket(Ticket t) => setState(() => tickets.insert(0, t));
}

