class AppShell extends StatelessWidget {
  const AppShell({super.key, required this.tickets, required this.employee, required this.tab, required this.onTab, required this.onCreate, required this.onLogout});
  final List<Ticket> tickets; final String employee; final int tab; final ValueChanged<int> onTab; final ValueChanged<Ticket> onCreate; final VoidCallback onLogout;
  @override Widget build(BuildContext context) {
    final pages = [HomePage(tickets: tickets, employee: employee, onCreate: onCreate), TicketListPage(tickets: tickets), KnowledgePage(), TeamPage(), MorePage(onLogout: onLogout)];
    return Scaffold(body: SafeArea(child: pages[tab]), bottomNavigationBar: NavigationBar(selectedIndex: tab, onDestinationSelected: onTab, destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home), label: 'Home'), NavigationDestination(icon: Icon(Icons.confirmation_number_outlined), selectedIcon: Icon(Icons.confirmation_number), label: 'Tickets'), NavigationDestination(icon: Icon(Icons.menu_book_outlined), selectedIcon: Icon(Icons.menu_book), label: 'Knowledge'), NavigationDestination(icon: Icon(Icons.groups_outlined), selectedIcon: Icon(Icons.groups), label: 'Team'), NavigationDestination(icon: Icon(Icons.more_horiz), label: 'More')]));
  }
}

